tape( 'if `N` is zero or the scalar constant is zero, the function returns the input matrix `A` unchanged (row-major)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var x;
	var y;

	data = rl;

	a = new Complex64Array( data.A );
	x = new Complex64Array( data.x );
	y = new Complex64Array( data.y );
	alpha = new Complex64Array( data.alpha );

	expected = new Complex64Array( data.A );

	out = cher( data.uplo, 0, alpha, x, data.strideX, data.offsetX, y, data.strideY, data.offsetY, a, data.strideA1, data.strideA2, data.offsetA );
	t.strictEqual( isSameComplex64Array( out, a ), true, 'returns expected value' );
	t.deepEqual( a, expected, 'returns expected value' );

	out = cher( data.uplo, data.N, 0.0, x, data.strideX, data.offsetX, y, data.strideY, data.offsetY, a, data.strideA1, data.strideA2, data.offsetA );
	t.strictEqual( isSameComplex64Array( out, a ), true, 'returns expected value' );
	t.deepEqual( a, expected, 'returns expected value' );

	t.end();
});

